// Kojlux Study Hub — service worker
//
// DO NOT EDIT public/sw.js DIRECTLY. It's generated by generate-sw.js
// (runs automatically on `npm run dev` / `npm run build`), which replaces
// __FIREBASE_CONFIG__ below with the values from your .env.
// Edit THIS template for any behavior changes.

importScripts('https://www.gstatic.com/firebasejs/10.13.1/firebase-app-compat.js');
importScripts('https://www.gstatic.com/firebasejs/10.13.1/firebase-messaging-compat.js');

firebase.initializeApp(__FIREBASE_CONFIG__);

// Activate an updated worker immediately so a fixed sw.js isn't stuck
// waiting behind an old one.
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (event) => event.waitUntil(self.clients.claim()));

const messaging = firebase.messaging();

// Fires when a push arrives while no tab has the app focused. Messages are
// "data"-only (see functions/index.ts) so we control tag, icon and deep link.
messaging.onBackgroundMessage((payload) => {
  const data = payload.data || {};

  return self.registration.showNotification(data.title || 'Kojlux Study Hub', {
    body: data.body || 'You have something to review.',
    tag: data.tag || 'kojlux-notification',
    renotify: true, // alert again even when replacing a same-tag notification
    data: { url: data.url || self.registration.scope },
    icon: `${self.registration.scope}icon.png`,
    badge: `${self.registration.scope}notification-badge.svg`,
  });
});

// Tapping the notification focuses an open tab if there is one, otherwise
// opens a new one at the deep-linked URL.
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  const target = new URL(
    (event.notification.data && event.notification.data.url) || self.registration.scope,
    self.registration.scope
  ).href;

  event.waitUntil(
    (async () => {
      const windowClients = await clients.matchAll({ type: 'window', includeUncontrolled: true });
      for (const client of windowClients) {
        if ('focus' in client) {
          await client.focus();
          if (client.url !== target && 'navigate' in client) {
            try { await client.navigate(target); } catch (_) { /* uncontrolled client */ }
          }
          return;
        }
      }
      if (clients.openWindow) await clients.openWindow(target);
    })()
  );
});